import type { FontMetrics } from "../kernel/geometry.ts";

/**
 * Geist's advance widths and kerning pairs in thousandths of an em, read from the font itself
 * (Geist-Variable, measured in Chrome). With them a line's width is known to the pixel before any
 * target draws it, which is what lets words be set one by one and still sit as the font spaces them.
 * Generated; do not edit by hand.
 */
const unpack = (advances: Record<string, number>, grouped: Record<string, string>): FontMetrics => {
  const kerning: Record<string, number> = {};
  for (const [value, pairs] of Object.entries(grouped)) {
    const chars = Array.from(pairs);
    for (let i = 0; i < chars.length; i += 2) kerning[chars[i]! + chars[i + 1]!] = Number(value);
  }
  return { unitsPerEm: 1000, advances, kerning };
};

